arguments.argument:
{
    object = -1;
    team = TEAM_SPECTATOR;
    class = CLASS_SCOUT;
    socket = -1;
    name = "";
    kicked = false;
    isBot = false;
    botRemovalPending = false;
    botRemovalDeadline = 0;

    // Bot navigation state (milestone 5). All of it lives on the Player rather than on
    // the Character so that it survives a death: the goal and the anti-thrash blacklist
    // are about the bot, not about the body it happens to be wearing. botPath and
    // botBlacklist own ds_ structures - botNavRelease is what gives them back.
    botPath = -1;
    botPathAt = 0;
    // Set when the goal changed while a route to the old one was still installed. That route
    // is kept so the bot keeps moving until a plan for the new goal exists (botSetGoal), and
    // this is what stops botPathKeys treating the end of it as an arrival. Cleared by the
    // first successful plan, which is normally the next tick.
    botPathStale = false;
    // Frame until which a failed search is not retried. Only consulted while a route is
    // installed: a failed plan now keeps the old route rather than clearing it, so without
    // this every event-driven caller in botPathKeys would re-run a full A* every tick for a
    // goal that cannot be reached.
    botPlanFailUntil = 0;
    botGoalX = 0;
    botGoalY = 0;
    botGoalNode = -1;
    botHasGoal = false;
    botArrived = false;
    // Suspends the objective layer for this one bot, so that whoever set the goal keeps
    // it. Nothing in the game ever sets this - it exists for the behaviour test harness
    // (gg2-agent's botscenario.js), which measures "can this bot walk from A to B on this
    // map" and needs B to still be B thirty ticks later. Without it botObjectiveUpdate
    // rewrites the goal from the game mode's objective on its own cadence and the test
    // silently measures the objective layer instead of the thing it asked about.
    //
    // A flag rather than a harness-side workaround on purpose: the alternative that does
    // not touch game code is deactivating the mode's objective objects, which does stop
    // botObjectiveUpdate - and also makes KothHUD throw every single frame, because it
    // reads KothControlPoint.locked unguarded. One line here is cheaper than a harness
    // that has to know which objects each of six game modes will miss.
    botGoalLocked = false;
    botReplanAt = 0;
    botEdgeFrom = -1;
    botEdgeTo = -1;
    botOffPathTicks = 0;
    botStuckTicks = 0;
    botLastX = 0;
    botLastY = 0;
    botJumpHeld = false;
    // Ticks since this bot left the ground on a jump edge. The arc it was given is a
    // position per tick, so following it needs to know which tick it is on; char.vspeed
    // would say, right up until terminal velocity pins it and every later tick reads
    // the same.
    botAirTicks = 0;
    // Whether this bot has already spent the second jump on the arc it is flying. Only a
    // NAV_EDGE_DOUBLEJUMP edge ever sets it; botPathKeys clears it on every takeoff, since
    // the game gives the jump back on landing (Character's Begin Step zeroes
    // doublejumpUsed while onground).
    botRejumped = false;
    // The rocket-jump hand-off, and the first time navigation has ever had an opinion
    // about where a bot is AIMING. botInputUpdate's header states the invariant these
    // three break: "combat owns ATTACK and SPECIAL, navigation owns LEFT/RIGHT/JUMP/DOWN".
    // A rocket jump needs the aim pointed at the bot's own feet and the trigger pulled on
    // the same tick it jumps, and both of those belong to botCombatUpdate.
    //
    // So botPathKeys does not take them - it ASKS, by setting these, and botInputUpdate
    // arbitrates after both halves have run. That keeps the two scripts independent (each
    // still returns its own keys, knowing nothing about the other) and puts the one place
    // they conflict in the one script whose job is already to see both.
    //
    // botRocketAim is -1 for "no request", or the aimDirection degrees to snap to.
    botRocketAim = -1;
    // Whether the request also wants the trigger. Kept separate from the aim rather than
    // folded into one flag because they are answers to different questions - "point here"
    // and "shoot now" - and the aim override is the half that would be reused by anything
    // else navigation ever needs to look at. Today botPathKeys always sets both together,
    // because the aim SNAPS and so needs no lead time.
    botRocketFire = false;
    botBlacklist = -1;
    botBlacklistQ = -1;
    // Which edge last put the bot somewhere its route did not go, and how many times in
    // a row. A marginal jump is worth one retry before it is taken away for seconds.
    botFailFrom = -1;
    botFailTo = -1;
    botFailCount = 0;
    botLastReplanX = -100000;
    botLastReplanY = -100000;
    botReplanNear = 0;
    botAttackKeys = 0;

    // Bot goal-layer and team-role state (milestone 7 tier 3). A goal used to be a world
    // point and nothing else; these are what let it also be "a place from which I can do
    // X" - a firing position on a generator, ground overlooking a point we already hold,
    // a spot beside the ally a Medic is following.
    //
    // botRole splits a team into attackers and defenders, which nothing in the bot code
    // distinguished before: every bot in every mode ran at the enemy objective. It is
    // assigned once per bot (botRoleAssign) rather than per tick, so a defender stays a
    // defender for a whole round and the split reads as team composition instead of as
    // indecision.
    botRole = BOT_ROLE_ATTACK;
    // A per-bot lateral offset applied to a shared objective, so a team of bots does not
    // converge on one pixel (M7 2.4) - derived from the Player id, so it is constant for
    // this bot's whole life and different from its team-mates'.
    botSpreadX = 0;
    // Whether this bot's installed route is currently counted in its team's edge
    // occupancy map (botOccupancyAdd). The counts are what make a team fan out across
    // the alternatives a map offers instead of filing down one route, and this flag is
    // what keeps adding and removing them idempotent - the route is added in one place
    // and removed in three, so without it a re-plan would decrement twice and leave a
    // count negative, which would make a busy edge *cheaper* rather than dearer.
    botOccupied = false;
    // Which team's map those counts went into. Not always player.team by the time they
    // come back out: ServerBalanceTeams moves a player between teams mid-round and can
    // pick a bot, and botReteamAll reassigns every bot on a map change.
    botOccupiedTeam = -1;
    // Whether the current goal came out of botGoalSpot rather than being the objective
    // itself, and until when spot goals are not to be tried again. botGoalSpot cannot
    // check reachability (it would cost an A* per candidate), so a spot in another
    // component presents as a goal that never plans - which, left alone, is a bot frozen
    // at spawn. Noticing that once and falling back to the plain objective for a while is
    // what keeps the goal layer from being able to make things worse than not having it.
    botGoalIsSpot = false;
    botSpotBanUntil = 0;
    // Whether botTarget is a player character rather than a piece of map furniture - a
    // Generator or a Sentry. Almost every field the combat chain reads off a target exists
    // only on a Character, so this gates each of those reads; botTargetIsChar is the script
    // that decides it. True by default and whenever there is no target, so a stray read is a
    // read of the Character fields rather than of nothing.
    botTargetIsChar = true;
    // Set when the current target was acquired by the long-range potshot roll (M7 3.5),
    // which widens the band the target is allowed to stay valid in - otherwise the shot
    // would be taken and the target dropped again on the very next tick.
    botPotshot = false;
    // Held at the spawn point for a moment after respawning so bots arrive in clumps
    // rather than in single file (M7 5.1). botAliveLast is only here to spot the
    // dead -> alive transition; nothing else needs it.
    botAliveLast = false;
    botRegroupUntil = 0;
    // Ticks spent on the ground failing to satisfy the current jump edge's takeoff gate.
    // botPathKeys zeroes it whenever the edge changes or the bot actually leaves the
    // ground; BOT_TAKEOFF_PATIENCE is what stops a gate that can refuse from refusing for
    // the rest of the round.
    botTakeoffTicks = 0;
    // -1 is "no run-up in progress"; see botPathKeys' takeoff gate and the botRunupCol script.
    botRunupAt = -1;
    // Set by botPathKeys while it is flying a jump edge's planned trajectory. Nothing may
    // touch the movement keys during that - the arc is a position per tick that the
    // generator validated, and any nudge in the air is permanent (M6 part 5) - so this is
    // what the evasion behaviours in botInputUpdate check before adding a press.
    botFlyingEdge = false;

    // Bot combat and difficulty state (milestone 6). botSkillApply writes the knobs from
    // one skill scalar when the bot is created; the defaults here are what a Player that
    // is not a bot keeps, and are the expert end of every knob so that a missing
    // botSkillApply shows up as a bot that behaves rather than as one that never fires.
    botSkill = 1;
    botAcquireTicks = 0;
    botFireDelayTicks = 0;
    botPerceiveTicks = 1;
    botAimInterval = 1;
    botTurnRate = 360;
    botAimErrorDeg = 0;
    // Suppression aim (M9 3.1): the node this bot is denying while it holds a target
    // it cannot see, and when that answer is next worth recomputing. -1 is "none".
    botSuppressNode = -1;
    botSuppressAt = 0;
    botAimConeDeg = 0;
    botMoveErrMult = 1;
    botHoldFireChance = 0;
    botLeadMode = BOT_LEAD_FULL;
    botSplashAim = true;
    // Who the bot is shooting at and when it first saw them: the acquisition delay, the
    // fire delay and the focus cone are all measured from botTargetAt.
    botTarget = noone;
    botTargetAt = 0;
    // Whether the target is currently in view, and the last tick it actually was - a
    // peek that breaks LOS keeps the target for a short memory window rather than
    // dropping it outright (M7 3.8), so this is what tells the aim snapshot below
    // whether it is allowed to update from the target's live position.
    botVisible = true;
    botLastSeenAt = 0;
    botAlly = noone;
    botHoldFire = false;
    botCloakAt = 0;
    // The perceived target - deliberately stale between refreshes, which is where
    // perception lag comes from - and the aim the bot is slewing towards.
    botAimSubject = noone;
    botPerceiveAt = 0;
    botSeeX = 0;
    botSeeY = 0;
    botSeeVX = 0;
    botSeeVY = 0;
    botAimAt = 0;
    botAimX = 0;
    botAimY = 0;
    botAimWant = 0;
    botAimDir = 0;

    // Diagnostics, so that "the stuck detector and the blacklist both fire" is a thing
    // that can be read off a running server rather than inferred from behaviour.
    botReplans = 0;
    // The tick botPathKeys last declared arrival, or -1 for "not since the last goal".
    // botSetGoal clears it, so it always belongs to the goal currently being followed.
    botArrivedAt = -1;
    botStuckFires = 0;
    // How many second jumps this bot has spent on a NAV_EDGE_DOUBLEJUMP arc. The same kind
    // of diagnostic as botReplans and botStuckFires beside it, and it exists for the same
    // reason: whether a Scout ever actually takes one of those edges is a question about a
    // running server, and every other way of asking it - watching one bot, sampling who is
    // mid-arc - misses a manoeuvre that lasts under a second.
    botDoubleJumps = 0;
    // How many rocket jumps this bot has taken, for exactly the reason botDoubleJumps
    // exists: whether these edges ever actually fire is a question about a running server,
    // and a manoeuvre that is over in a second is not something sampling can catch.
    botRocketJumps = 0;
    botBlacklistFires = 0;
    // What was blacklisted, not just how often - "off:251>254@1830,stk:254>255@1902",
    // reason:from>to@frame, comma separated and deliberately space-free so the scenario
    // runner's field parser can carry it in one token. Bounded, because this is a
    // diagnostic on every bot in every round and an unbounded string on a long round is
    // a leak; the first few entries are the ones worth having anyway.
    botBlacklistLog = "";
    botOffRouteFires = 0;

    // client setting stuff; set to defaults
    queueJump = false;

    //stat tracking array
    stats[KILLS] = 0;
    stats[DEATHS] = 0;
    stats[CAPS] = 0;
    stats[ASSISTS] = 0;
    stats[DESTRUCTION] = 0;
    stats[STABS] = 0;
    stats[HEALING] = 0;
    stats[DEFENSES] = 0;
    stats[INVULNS] = 0;
    stats[BONUS] = 0;
    stats[DOMINATIONS] = 0;
    stats[REVENGE] = 0;
    stats[POINTS] = 0;

    //statistic array for single life/arena
    roundStats[KILLS] = 0;
    roundStats[DEATHS] = 0;
    roundStats[CAPS] = 0;
    roundStats[ASSISTS] = 0;
    roundStats[DESTRUCTION] = 0;
    roundStats[STABS] = 0;
    roundStats[HEALING] = 0;
    roundStats[DEFENSES] = 0;
    roundStats[INVULNS] = 0;
    roundStats[BONUS] = 0;
    roundStats[DOMINATIONS] = 0;
    roundStats[REVENGE] = 0;
    roundStats[POINTS] = 0;

    timesChangedCapLimit = 0;

    lastKnownx = 0;
    lastKnowny = 0;

    humiliated = 0;

    deathmatch_respawn_bypass = 0;

    //Sentries for Engies
    sentry = noone;

    // Haxxy rewards
    rewards = ds_map_create();
    badges = ds_list_create();
    ghost = noone;

    //Domination Kill Table
    dominationKills = domination_kills_create();

    corpse = noone;
}
